import json
import uuid
import hashlib
import datetime
import os
from typing import Dict, List, Optional, Any

# Define Metadata Schema
class DocumentMetadata:
    def __init__(self, jurisdiction: str, court: str, year: int, citation: str, judge: str, parties: List[str], status: str):
        self.jurisdiction = jurisdiction
        self.court = court
        self.year = year
        self.citation = citation
        self.judge = judge
        self.parties = parties
        self.status = status
        self.version = "1.0.0"
        self.created_at = datetime.datetime.now().isoformat()
        self.updated_at = self.created_at
        self.creator = "system"
        self.last_modified_by = self.creator
        self.document_hash = ""

    def to_dict(self) -> Dict[str, Any]:
        return {
            "jurisdiction": self.jurisdiction,
            "court": self.court,
            "year": self.year,
            "citation": self.citation,
            "judge": self.jurisdiction,
            "parties": self.parties,
            "status": self.status,
            "version": self.version,
            "created_at": self.created_at,
            "updated_at": self.updated_at,
            "creator": self.creator,
            "last_modified_by": self.last_modified_by,
            "document_hash": self.document_hash
        }

    @staticmethod
    def from_dict(data: Dict[str, Any]):
        return DocumentMetadata(
            jurisdiction=data["jurisdiction"],
            court=data["court"],
            year=data["year"],
            citation=data["citation"],
            judge=data["judge"],
            parties=data["parties"],
            status=data["status"]
        )

# Immutable storage and versioning
class ImmutableStorage:
    def __init__(self, storage_path: str = "immutable_storage/"):
        self.storage_path = storage_path
        os.makedirs(self.storage_path, exist_ok=True)
        self.audit_log_path = os.path.join(self.storage_path, "audit.log")
        os.makedirs(os.path.dirname(self.audit_log_path), exist_ok=True)

    def store_document(self, document_id: str, content: str, metadata: DocumentMetadata):
        document_hash = self._hash_content(content)
        metadata.document_hash = document_hash
        file_path = os.path.join(self.storage_path, f"{document_id}.json")
        with open(file_path, "w") as f:
            json.dump(metadata.to_dict(), f)
        self._log_audit(document_id, "stored", document_hash, metadata)

    def retrieve_document(self, document_id: str) -> Optional[Dict[str, Any]]:
        file_path = os.path.join(self.storage_path, f"{document_id}.json")
        if not os.path.exists(file_path):
            return None
        with open(file_path, "r") as f:
            return json.load(f)

    def _hash_content(self, content: str) -> str:
        return hashlib.sha256(content.encode()).hexdigest()

    def _log_audit(self, document_id: str, action: str, document_hash: str, metadata: DocumentMetadata):
        log_entry = {
            "document_id": document_id,
            "action": action,
            "document_hash": document_hash,
            "metadata_hash": self._hash_metadata(metadata),
            "timestamp": datetime.datetime.now().isoformat(),
            "version": metadata.version,
            "user": metadata.last_modified_by
        }
        with open(self.audit_log_path, "a") as f:
            f.write(json.dumps(log_entry) + "\n")

    def _hash_metadata(self, metadata: DocumentMetadata) -> str:
        return self._hash_content(json.dumps(metadata.to_dict()))

# Version control system
class DocumentVersionControl:
    def __init__(self, storage: ImmutableStorage):
        self.storage = storage
        self.version_history_path = os.path.join(self.storage.storage_path, "version_history.json")
        self._init_version_history()

    def _init_version_history(self):
        if not os.path.exists(self.version_history_path):
            with open(self.version_history_path, "w") as f:
                json.dump({}, f)

    def get_version_history(self, document_id: str) -> List[Dict[str, Any]]:
        with open(self.version_history_path, "r") as f:
            history = json.load(f)
        return history.get(document_id, [])

    def add_version(self, document_id: str, metadata: DocumentMetadata, content: str):
        version = self._generate_version()
        metadata.version = version
        metadata.updated_at = datetime.datetime.now().isoformat()
        self.storage.store_document(document_id, content, metadata)

        version_entry = {
            "version": version,
            "timestamp": metadata.updated_at,
            "user": metadata.last_modified_by,
            "document_hash": metadata.document_hash
        }

        self._update_version_history(document_id, version_entry)

    def _generate_version(self) -> str:
        # Simple semantic versioning
        return f"1.0.{int(datetime.datetime.now().timestamp()) % 1000000}"

    def _update_version_history(self, document_id: str, version_entry: Dict[str, Any]):
        with open(self.version_history_path, "r") as f:
            history = json.load(f)
        if document_id not in history:
            history[document_id] = []
        history[document_id].append(version_entry)
        with open(self.version_history_path, "w") as f:
            json.dump(history, f)

