import pytest

def test_metadata_schema():
    metadata = DocumentMetadata(
        jurisdiction="Federal",
        court="Supreme Court",
        year=2023,
        citation="589 U.S. 1",
        judge="Justice A",
        parties=["Plaintiff", "Defendant"],
        status="current"
    )
    assert metadata.jurisdiction == "Federal"
    assert metadata.court == "Supreme Court"
    assert metadata.year == 2023
    assert metadata.citation == "589 U.S. 1"
    assert metadata.judge == "Justice A"
    assert metadata.parties == ["Plaintiff", "Defendant"]
    assert metadata.status == "current"
    assert metadata.version == "1.0.0"

def test_version_control():
    storage = ImmutableStorage()
    doc_id = str(uuid.uuid4())
    content = "This is a legal document."
    metadata = DocumentMetadata(
        jurisdiction="Federal",
        court="Supreme Court",
        year=2023,
        citation="589 U.S. 1",
        judge="Justice A",
        parties=["Plaintiff", "Defendant"],
        status="current"
    )
    version_control = DocumentVersionControl(storage)
    version_control.add_version(doc_id, metadata, content)
    version_control.add_version(doc_id, metadata, content + " Amendment.")
    history = version_control.get_version_history(doc_id)
    assert len(history) == 2
    assert history[0]["version"] != history[1]["version"]

def test_retrieval_and_integrity():
    storage = ImmutableStorage()
    doc_id = str(uuid.uuid4())
    content = "Original document content."
    metadata = DocumentMetadata(
        jurisdiction="Federal",
        court="Supreme Court",
        year=2023,
        citation="589 U.S. 1",
        judge="Justice A",
        parties=["Plaintiff", "Defendant"],
        status="current"
    )
    version_control = DocumentVersionControl(storage)
    version_control.add_version(doc_id, metadata, content)
    retrieved = storage.retrieve_document(doc_id)
    assert retrieved is not None
    assert retrieved["document_hash"] == storage._hash_content(content)

def test_audit_trail():
    storage = ImmutableStorage()
    doc_id = str(uuid.uuid4())
    content = "Legal text."
    metadata = DocumentMetadata(
        jurisdiction="Federal",
        court="Supreme Court",
        year=2023,
        citation="589 U.S. 1",
        judge="Justice A",
        parties=["Plaintiff", "Defendant"],
        status="current"
    )
    storage.store_document(doc_id, content, metadata)
    with open(storage.audit_log_path, "r") as f:
        logs = [json.loads(line) for line in f]
    assert len(logs) > 0
    assert logs[0]["document_id"] == doc_id
    assert logs[0]["action"] == "stored"

